const dashState={target:10000,range:'month',start:'',end:'',tasks:[],reminders:[],nps:[],activities:[],showPanels:true,dialog:null};
const dashCurrency=n=>new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL',maximumFractionDigits:0}).format(n||0);
const dashToday=()=>new Date().toISOString().slice(0,10);
function dashClients(){return clientsState.items.filter(c=>!c.archived)}
function dashEarned(date){return dashClients().reduce((sum,c)=>{if(!c.start||!c.months)return sum;const start=new Date(c.start+'T12:00:00'),end=new Date(start);end.setMonth(end.getMonth()+Number(c.months));return date>=start&&date<end?sum+(Number(c.monthly)||0):sum},0)}
function dashPeriod(){const now=new Date(),start=dashState.start?new Date(dashState.start+'T00:00:00'):new Date(now.getFullYear(),now.getMonth(),1),end=dashState.end?new Date(dashState.end+'T23:59:59'):now;return {start,end}}
function dashValues(){const p=dashPeriod(),total=dashEarned(new Date()),newClients=dashClients().filter(c=>{let d=new Date(c.start+'T12:00:00');return d>=p.start&&d<=p.end}).length;return {total,newClients,closed:dashClients().filter(c=>c.stage==='Fechado').length}}
function dashLine(){const now=new Date(),points=Array.from({length:6},(_,i)=>{const d=new Date(now.getFullYear(),now.getMonth()-5+i,15);return {label:d.toLocaleString('pt-BR',{month:'short'}),value:dashEarned(d)}});const max=Math.max(1000,...points.map(p=>p.value))*1.2;const coords=points.map((p,i)=>`${35+i*125},${210-p.value/max*175}`);const area=`M ${coords[0]} L ${coords.slice(1).join(' L ')} L 660,210 L 35,210 Z`;return `<svg role="img" aria-label="Faturamento estimado dos últimos seis meses" viewBox="0 0 700 240" preserveAspectRatio="none"><defs><linearGradient id="g" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#ff6400" stop-opacity=".4"/><stop offset="1" stop-color="#ff6400" stop-opacity=".02"/></linearGradient></defs><path d="M35 35H660M35 95H660M35 155H660M35 210H660" stroke="#34425a" stroke-dasharray="3 5"/><path d="${area}" fill="url(#g)"/><polyline points="${coords.join(' ')}" fill="none" stroke="#ff6400" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/>${coords.map(x=>`<circle cx="${x.split(',')[0]}" cy="${x.split(',')[1]}" r="4" fill="#ff6400"/>`).join('')}</svg><div class="chart-labels">${points.map(p=>`<span>${p.label}</span>`).join('')}</div>`}
function dashList(items,fn,empty){return items.length?`<ul class="dash-list">${items.map(fn).join('')}</ul>`:`<div class="dash-empty">${empty}</div>`}
function renderDashboard(){document.querySelector('.workspace').classList.remove('clients-mode');document.querySelector('.workspace').classList.add('dashboard-mode');document.querySelector('#page-title').textContent='Dashboard';const v=dashValues(),pct=Math.min(100,Math.round(v.total/Math.max(1,dashState.target)*100)),today=dashToday();const overdue=dashState.tasks.filter(t=>!t.done&&t.due<today),due=dashState.tasks.filter(t=>!t.done&&t.due===today),finished=dashState.tasks.filter(t=>t.done).length;const serviceTotals=new Map();dashClients().forEach(c=>{if(c.project)serviceTotals.set(c.project,(serviceTotals.get(c.project)||0)+(Number(c.monthly)||0))});const services=[...serviceTotals].sort((a,b)=>b[1]-a[1]);const maxService=Math.max(1,...services.map(s=>s[1]));const scores=dashState.nps.map(x=>Number(x.score)),nps=scores.length?Math.round((scores.filter(x=>x>=9).length-scores.filter(x=>x<=6).length)/scores.length*100):0;const w=document.querySelector('.workspace');w.innerHTML=`<div class="dash-wrap"><div class="dash-head"><div><h2>Dashboard</h2><p>Visão geral do seu negócio · Dados demonstrativos</p></div><div class="dash-controls"><select id="dash-range" aria-label="Filtros rápidos"><option value="month" ${dashState.range==='month'?'selected':''}>Este mês</option><option value="7" ${dashState.range==='7'?'selected':''}>Últimos 7 dias</option><option value="30" ${dashState.range==='30'?'selected':''}>Últimos 30 dias</option><option value="custom" ${dashState.range==='custom'?'selected':''}>Período personalizado</option></select><input id="dash-start" type="date" aria-label="Data inicial" value="${dashState.start}"/><span>–</span><input id="dash-end" type="date" aria-label="Data final" value="${dashState.end}"/><button class="dash-btn" data-dash="panels">${dashState.showPanels?'Ocultar':'Mostrar'} painéis</button><button class="dash-btn" data-dash="goal">Editar meta</button></div></div><div class="dash-top"><div class="dash-card"><div class="dash-card-head"><h3>Meta de Receita</h3><span class="accent">◎</span></div><p>Progresso do mês atual</p><div class="dash-meta"><span>${dashCurrency(v.total)}</span><strong class="accent">${dashCurrency(dashState.target)}</strong></div><div class="dash-progress" style="--progress:${pct}%"><i></i></div><div class="dash-meta"><span>${pct}% alcançado</span><span>Faltam ${dashCurrency(Math.max(0,dashState.target-v.total))}</span></div></div><div class="dash-card"><h3>＄</h3><div class="big positive">${dashCurrency(v.total)}</div><p>Faturamento mensal estimado</p></div><div class="dash-card"><h3>♧</h3><div class="big">${v.newClients}</div><p>Novos clientes no período</p></div><div class="dash-card"><h3>↗</h3><div class="big accent">${v.closed}</div><p>Clientes fechados</p></div></div><section class="dash-card dash-chart"><div class="dash-card-head"><div><h3>Análise Financeira Consolidada</h3><p>Estimativa por contratos ativos · últimos 6 meses</p></div><button class="dash-btn" data-dash="finance">Ver clientes</button></div>${dashLine()}</section><div id="dash-panels" ${dashState.showPanels?'':'hidden'}><div class="dash-grid two"><section class="dash-card"><h3>Receita por serviço</h3>${services.length?services.map(([name,n])=>`<div class="dash-service-row"><span title="${esc(name)}">${esc(name)}</span><span class="bar" style="--bar:${Math.round(n/maxService*100)}%"><i></i></span><b>${dashCurrency(n)}</b></div>`).join(''):'<div class="dash-empty">Nenhum serviço vinculado</div>'}</section><section class="dash-card"><h3>Composição da carteira</h3>${dashList(services,([name,n])=>`<li class="dash-row"><span>${esc(name)}</span><b>${Math.round(n/Math.max(1,v.total)*100)}%</b></li>`,'Nenhum cliente ativo')}</section></div><div class="dash-grid"><section class="dash-card"><div class="dash-card-head"><h3>Tarefas Diárias</h3><button class="dash-btn" data-dash="task">＋ Criar tarefa</button></div>${dashList(due,t=>`<li class="dash-row"><label><input type="checkbox" data-dash="complete" data-id="${t.id}"> ${esc(t.title)}</label><small>${esc(t.client||'')}</small></li>`,'Nenhuma tarefa para hoje')}</section><section class="dash-card"><h3>Projetos Recentes</h3>${dashList(dashClients().slice(0,5),c=>`<li><button data-dash="client" data-id="${c.id}">${esc(c.project||c.name)}</button><small>${esc(c.name)}</small></li>`,'Nenhum projeto cadastrado')}</section><section class="dash-card"><h3>Atividade Recente</h3>${dashList(dashState.activities.slice(0,6),a=>`<li>${esc(a.text)}<small>${esc(a.date)}</small></li>`,'As ações realizadas aparecerão aqui')}</section></div><div class="dash-grid"><section class="dash-card"><div class="dash-card-head"><h3>Tarefas Atrasadas</h3><b class="accent">${overdue.length}</b></div>${dashList(overdue,t=>`<li class="dash-row"><label><input type="checkbox" data-dash="complete" data-id="${t.id}"> ${esc(t.title)}</label><small>${esc(t.due)}</small></li>`,'Nenhuma tarefa atrasada')}</section><section class="dash-card"><h3>Tarefas para Hoje</h3>${dashList(due,t=>`<li class="dash-row"><span>${esc(t.title)}</span><button data-dash="complete" data-id="${t.id}">Concluir</button></li>`,'Nenhuma tarefa para hoje')}</section><section class="dash-card"><h3>Lembretes Rápidos</h3><form id="reminder-form" class="dash-input-row"><input name="reminder" maxlength="120" required placeholder="Adicionar lembrete..." aria-label="Adicionar lembrete"><button class="dash-btn orange" aria-label="Salvar lembrete">＋</button></form>${dashList(dashState.reminders,r=>`<li class="dash-row"><span>${esc(r.text)}</span><button data-dash="remove-reminder" data-id="${r.id}" aria-label="Excluir lembrete">×</button></li>`,'Nenhum lembrete ainda')}</section></div><div class="dash-grid"><section class="dash-card"><h3>Próximas Reuniões</h3><div class="dash-empty">Nenhuma reunião agendada</div><button class="dash-btn" data-dash="meeting">Agendar reunião</button></section><section class="dash-card"><h3>Estoque Baixo</h3><div class="dash-empty">Estoque sem produtos cadastrados</div><button class="dash-btn" data-dash="products">Ver produtos</button></section><section class="dash-card"><h3>Conteúdos do Dia</h3><div class="dash-empty">Nenhum conteúdo programado</div><button class="dash-btn" data-dash="content">Ver calendário</button></section></div><div class="dash-grid two"><section class="dash-card"><h3>Saúde de Relacionamento</h3><p>Clientes sem registro de reunião</p>${dashList(dashClients(),c=>`<li class="dash-row"><button data-dash="client" data-id="${c.id}">${esc(c.name)}</button><span class="accent">Sem reunião</span></li>`,'Nenhum cliente cadastrado')}</section><section class="dash-card"><div class="dash-card-head"><h3>Saúde dos Clientes (NPS)</h3><button class="dash-btn" data-dash="nps">＋ Registrar</button></div><div class="dash-nps"><div>NPS<b>${nps}</b></div><div>Promotores<b>${scores.filter(x=>x>=9).length}</b></div><div>Neutros<b>${scores.filter(x=>x>=7&&x<=8).length}</b></div><div>Detratores<b>${scores.filter(x=>x<=6).length}</b></div></div><p>${scores.length?'Respostas registradas: '+scores.length:'Registre uma avaliação para começar.'}</p></section></div><section class="dash-card" style="text-align:center;margin-top:15px;padding:35px"><h3>Diagnóstico do negócio</h3><p>Resumo baseado nos clientes, contratos e tarefas cadastrados nesta visualização.</p><button class="dash-btn orange" data-dash="diagnosis">Gerar diagnóstico</button><div id="dash-diagnosis"></div></section></div></div>`}
function dashOpen(kind){dashState.dialog=kind;document.querySelector('.dash-dialog')?.remove();let content='';if(kind==='goal')content=`<label>Meta mensal (R$)<input name="value" type="number" min="1" required value="${dashState.target}"></label>`;if(kind==='task')content='<label>Descrição da tarefa<input name="title" required maxlength="120"></label><label>Vencimento<input name="due" type="date" required></label><label>Cliente<input name="client" placeholder="Opcional"></label>';if(kind==='nps')content=`<label>Cliente<select name="client" required>${dashClients().map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('')}</select></label><label>Nota de 0 a 10<input name="score" type="number" min="0" max="10" required></label>`;if(kind==='meeting')content='<label>Reunião<input name="title" required maxlength="120"></label><label>Data<input name="due" type="date" required></label>';if(!content)return;const root=document.createElement('div');root.className='dash-dialog';root.innerHTML=`<div role="dialog" aria-modal="true" aria-label="${kind}"><h3>${{goal:'Editar meta',task:'Criar tarefa',nps:'Registrar NPS',meeting:'Agendar reunião'}[kind]}</h3><form id="dash-form">${content}<div class="actions"><button type="button" class="dash-btn" data-dash="close">Cancelar</button><button class="dash-btn orange" type="submit">Salvar</button></div></form></div>`;document.body.append(root);root.querySelector('input,select')?.focus()}
function dashAction(action,id){if(['goal','task','nps','meeting'].includes(action)){dashOpen(action);return}if(action==='close'){document.querySelector('.dash-dialog')?.remove();return}if(action==='panels'){dashState.showPanels=!dashState.showPanels;renderDashboard();return}if(action==='client'){openModal('details',id);return}if(action==='finance'){menu.querySelector('[data-page="Clientes"]').click();return}if(action==='products'||action==='content'){menu.querySelector(`[data-page="${action==='products'?'Produtos':'Conteúdos'}"]`)?.click();return}if(action==='complete'){const t=dashState.tasks.find(t=>t.id===id);if(t){t.done=true;dashState.activities.unshift({text:'Tarefa concluída: '+t.title,date:new Date().toLocaleDateString('pt-BR')});renderDashboard()}return}if(action==='remove-reminder'){dashState.reminders=dashState.reminders.filter(r=>r.id!==id);renderDashboard();return}if(action==='diagnosis'){const v=dashValues();document.querySelector('#dash-diagnosis').innerHTML=`<p>Carteira ativa: ${dashClients().length} clientes · Receita mensal estimada: ${dashCurrency(v.total)} · Tarefas pendentes: ${dashState.tasks.filter(t=>!t.done).length} · Meta alcançada: ${Math.round(v.total/Math.max(1,dashState.target)*100)}%.</p>`}}
document.addEventListener('click',e=>{const b=e.target.closest('[data-dash]');if(b)dashAction(b.dataset.dash,b.dataset.id);if(e.target.classList.contains('dash-dialog'))e.target.remove()});document.addEventListener('submit',e=>{if(e.target.id==='reminder-form'){e.preventDefault();const v=new FormData(e.target).get('reminder').trim();if(v)dashState.reminders.unshift({id:String(Date.now()),text:v});renderDashboard()}if(e.target.id==='dash-form'){e.preventDefault();const f=Object.fromEntries(new FormData(e.target));if(dashState.dialog==='goal')dashState.target=Number(f.value)||10000;if(dashState.dialog==='task')dashState.tasks.unshift({id:String(Date.now()),title:f.title.trim(),due:f.due,client:f.client,done:false});if(dashState.dialog==='meeting')dashState.tasks.unshift({id:String(Date.now()),title:'Reunião: '+f.title.trim(),due:f.due,client:'',done:false});if(dashState.dialog==='nps')dashState.nps.push({client:f.client,score:Number(f.score)});dashState.activities.unshift({text:({goal:'Meta atualizada',task:'Tarefa criada',meeting:'Reunião agendada',nps:'NPS registrado'})[dashState.dialog],date:new Date().toLocaleDateString('pt-BR')});document.querySelector('.dash-dialog')?.remove();renderDashboard()}});document.addEventListener('change',e=>{if(!['dash-range','dash-start','dash-end'].includes(e.target.id))return;if(e.target.id==='dash-range'){dashState.range=e.target.value;const now=new Date();if(e.target.value==='month')dashState.start=new Date(now.getFullYear(),now.getMonth(),1).toISOString().slice(0,10);else if(e.target.value==='7'||e.target.value==='30')dashState.start=new Date(now.getTime()-(Number(e.target.value)-1)*864e5).toISOString().slice(0,10);dashState.end=e.target.value==='custom'?dashState.end:dashToday()}else{dashState.range='custom';dashState.start=document.querySelector('#dash-start').value;dashState.end=document.querySelector('#dash-end').value}renderDashboard()});
